\boxed{
\begin{aligned}
\mathrm ds^2={}&
-\left(1-\frac{2GMr}{\rho^2}\right)\mathrm dt^2
-\frac{2GMar\sin^2\theta}{\rho^2}
\left(\mathrm dt\,\mathrm d\phi+\mathrm d\phi\,\mathrm dt\right)\\
&+\frac{\rho^2}{\Delta}\,\mathrm dr^2
+\rho^2\mathrm d\theta^2
+\frac{\sin^2\theta}{\rho^2}
\left[(r^2+a^2)^2-a^2\Delta\sin^2\theta\right]\mathrm d\phi^2 .
\end{aligned}
}
\tag{6.70}
